"""Module 09 (EASA M04 SM02 Printed circuit boards). Every closed item carries an 'evidence' regex checked against the EASA OCR text of the cited PDF page
(build/verify/verify_m09.py). EASA has no multiple-choice items: book questions (2-1..2-13) become worked/open items with the printed answers."""
import os, sys, json
sys.path.insert(0, os.path.dirname(__file__))
from _lib import *
T = dict(mfg=('PCB construction and materials', 'Cấu tạo và vật liệu PCB'), tech=('Mounting technologies and soldering', 'Công nghệ lắp linh kiện và hàn'), via=('Multilayer boards and vias', 'PCB nhiều lớp và via'), esd=('Static electricity and ESD', 'Tĩnh điện và ESD'), prot=('ESD protection and handling', 'Chống ESD và thao tác'), rep=('PCB repair and LRMs', 'Sửa PCB và LRM'))
TT = {k: B(*v) for k, v in T.items()}
items = []; EVID = {}
def pg(n): return f'EASA M04 SM02, p.2.{n-87} (PDF p.{n})', f'EASA M04 SM02, tr.2.{n-87} (PDF tr.{n})'
def mcq(tp, n, qen, qvi, ans, wrongs, xe, xv, ev, lvl=1, fig=None):
    opts = [ans] + wrongs; it = dict(kind='mcq', q=B(qen, qvi), opts=O(opts), correct=0, explain=B(xe, xv), level=lvl, topic=TT[tp], src=B(*pg(n)), origin='bo_sung', fixed_order=False, check='EASA text', evidence=dict(page=n, rx=ev))
    if fig: it['fig'] = fig
    items.append(it)
def tf(tp, n, en, vi, v, xe, xv, ev, lvl=1):
    items.append(dict(kind='tf', q=B(en, vi), opts=[B('True', 'Đúng'), B('False', 'Sai')], correct=0 if v else 1, explain=B(xe, xv), level=lvl, topic=TT[tp], src=B(*pg(n)), origin='bo_sung', fixed_order=True, check='EASA text', evidence=dict(page=n, rx=ev)))
Y = lambda en, vi=None: (en, vi if vi is not None else en)
